export default class BerthSchedule extends React.Component {
  state = { berths: [], loading: true };
  componentDidMount() { this.load(); this.timer = setInterval(() => this.load(), 30000); }
  componentDidUpdate(prev) { if (prev.portId !== this.props.portId) this.load(); }
  componentWillUnmount() { clearInterval(this.timer); }
  load = async () => {
    const berths = await getBerths(this.props.portId);
    this.setState({ berths, loading: false });
  };
  render() {
    if (this.state.loading) return <Spinner />;
    return <ul className="berths">{this.state.berths.map(b => <BerthRow key={b.id} berth={b} />)}</ul>;
  }
}

