import { useEffect, useState } from 'react';

export default function BerthSchedule({ portId }) {
  const [berths, setBerths] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      const data = await getBerths(portId);
      if (!cancelled) { setBerths(data); setLoading(false); }
    };
    load();
    const timer = setInterval(load, 30000);
    return () => { cancelled = true; clearInterval(timer); };
  }, [portId]);

  if (loading) return <Spinner />;
  return (
    <ul className="berths">
      {berths.map(b => <BerthRow key={b.id} berth={b} />)}
    </ul>
  );
}
